UPDATE point_balance
SET balance = balance - #{amount},
    reserved_amount = reserved_amount - #{amount},
    updated_at = NOW(6)
WHERE member_id = #{memberId}
  AND balance >= #{amount}
  AND reserved_amount >= #{amount}

UPDATE point_balance
SET reserved_amount = reserved_amount - #{amount}, updated_at = NOW(6)
WHERE member_id = #{memberId}
  AND reserved_amount >= #{amount}
